(()=>{'use strict';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let context=null,panes=new Map(),epoch=0,timer=null,inflight=false,opening=new Map(),requestSerial=0,contextLocked=false;const root=()=>document.getElementById('split-workspace');const $=(id)=>document.getElementById(id);function people(){if(!context)return[];return[context.state.room.owner,...context.state.room.members].filter((p,i,a)=>a.findIndex(x=>x.id===p.id)===i);}const myId=()=>context.state.me.id;function node(id){return root()?.querySelector('[data-pane="'+id+'"]');}function field(id){return node(id)?.querySelector('textarea');}async function call(id,body){const token=context.self,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/buffer?course='+encodeURIComponent(context.courseId)+'&room='+encodeURIComponent(context.roomId)+'&learner='+encodeURIComponent(id),{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify({self:token,courseId:context.courseId,roomId:context.roomId,learnerId:id,...body}):undefined});const value=await r.json();if(!r.ok)throw Object.assign(Error(value.error||'Editor request failed'),{status:r.status});return value;}finally{clearTimeout(timeout);}}function setStatus(id,text){const el=node(id)?.querySelector('.pane-status');if(el)el.textContent=text;}function locked(id,message){const p=panes.get(id);if(p){p.lockVersion=(p.lockVersion||0)+1;p.locked=true;p.canEdit=false;}if(field(id))field(id).readOnly=true;const b=node(id)?.querySelector('[data-command="save"]');if(b)b.disabled=true;setStatus(id,message+' Your existing text is kept for copying.');}function shell(){if(!root())return;root().innerHTML='<div class="split-top"><div><span class="eyebrow">YOUR STUDY DESK</span><h2>Start with your code.</h2><p>Click a teammate to open their editor alongside yours.</p></div><button class="button outline" id="only-mine">Only my editor</button></div><div id="participant-rail" class="participant-rail" aria-label="Open a teammate editor"></div><div id="split-grid" class="split-grid"></div>';renderRoster();$('only-mine').onclick=()=>{const dirty=[...panes].filter(([id,p])=>id!==myId()&&p.dirty);if(dirty.length&&!confirm('Close the other editors and discard their unsaved changes? Copy or save them first to keep them.'))return;for(const id of [...panes.keys()])if(id!==myId())panes.delete(id);for(const id of [...opening.keys()])if(id!==myId())opening.delete(id);renderPanes();};}function renderRoster(){if(!$('participant-rail'))return;$('participant-rail').innerHTML=people().map(p=>`<button class="participant-chip ${panes.has(p.id)?'opened':''}" data-person="${p.id}" aria-pressed="${panes.has(p.id)}"><span class="person-initial">${p.photoUrl?'<img class="learner-avatar-image" src="'+esc(p.photoUrl)+'" alt="" loading="lazy">':esc(p.handle.slice(0,2).toUpperCase())}</span><span>${esc(p.handle)}${p.id===myId()?' · you':''}</span><span class="person-open">${panes.has(p.id)?'−':'+'}</span></button>`).join('');$('participant-rail').querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{const id=b.dataset.person;if(id===myId()){field(id)?.focus();return;}if(panes.has(id))close(id);else open(id);});}function renderPanes(){if(!$('split-grid'))return;const grid=$('split-grid');grid.style.setProperty('--pane-count',Math.max(1,panes.size));grid.innerHTML=[...panes].map(([id,p])=>`<section class="editor-pane ${id===myId()?'own-pane':''}" data-pane="${id}" aria-label="${esc(p.learner.handle)} editor"><header class="pane-heading"><div><span class="pane-icon">{ }</span><strong>${esc(p.learner.handle)}${id===myId()?' <small>YOU</small>':''}</strong></div>${id!==myId()?'<button class="pane-close" data-command="close" aria-label="Close this editor">×</button>':'<span class="pane-owner-dot"></span>'}</header><div class="pane-subhead"><span>${esc(context.state.room.language.toUpperCase())}</span><span class="pane-access">${p.error?'UNAVAILABLE':p.canEdit?'EDIT ACCESS':'VIEW ONLY'} · ${p.shared?'SHARED':'PRIVATE'}</span></div><div class="editor-surface"><span class="line-gutter" aria-hidden="true"></span><textarea spellcheck="false" maxlength="16000" aria-label="Code by ${esc(p.learner.handle)}" placeholder="Write your code here…" ${!p.canEdit||p.locked?'readonly':''}>${esc(p.text)}</textarea></div><div class="pane-change" ${p.conflict?'':'hidden'}>Newer saved code is available. Your unsaved edits are kept.</div><div class="pane-buttons"><button class="button" data-command="save" ${!p.canEdit||p.locked?'disabled':''}>Save</button><button class="button outline" data-command="copy">Copy</button><button class="button outline" data-command="reload">Load latest</button></div><p class="pane-status" role="status">${esc(p.status|| (p.dirty?'Unsaved changes':p.error||'Saved version '+p.revision))}</p>${id===myId()&&p.own?`<div class="pane-sharing">${p.roomOwnerBuffer?'<p>Room-owner editor: shared with invited members. Change their editing access under Room settings.</p>':`<label><input type="checkbox" data-command="share" ${p.permissionsBusy||p.permissionsUnknown?'disabled':''} ${p.shared?'checked':''}> Share my saved code with this room</label><p>${p.permissionsUnknown?'Permission state could not be confirmed. Choose Load latest before changing access.':p.shared?'Invited members can open your editor. You choose who may edit below.':'Your personal editor is private until you share it.'}</p><div class="pane-grants">${people().filter(x=>x.id!==myId()).map(x=>`<label><input type="checkbox" data-grantee="${x.id}" ${p.editors?.some(e=>e.id===x.id)?'checked':''} ${!p.shared||p.permissionsBusy||p.permissionsUnknown?'disabled':''}><span>Let ${esc(x.handle)} edit my code</span></label>`).join('')}</div>`}</div>`:''}</section>`).join('');for(const [id,p]of panes){const el=node(id),ed=field(id),gutter=el.querySelector('.line-gutter');ed.value=p.text;const lines=()=>gutter.textContent=Array.from({length:Math.max(18,ed.value.split('\n').length)},(_,i)=>i+1).join('\n');lines();ed.oninput=()=>{p.text=ed.value;p.dirty=true;setStatus(id,'Unsaved changes. Choose Save to share this version.');lines();};ed.onscroll=()=>gutter.scrollTop=ed.scrollTop;ed.onkeydown=e=>{if(e.key==='Tab'&&!ed.readOnly){e.preventDefault();ed.setRangeText('    ',ed.selectionStart,ed.selectionEnd,'end');ed.oninput();}};el.querySelectorAll('[data-command]').forEach(b=>{if(b.dataset.command==='share'){b.onchange=()=>share(id,b.checked);return;}b.onclick=()=>({save:()=>save(id),copy:()=>copy(id),reload:()=>reload(id),close:()=>close(id)})[b.dataset.command]?.();});el.querySelectorAll('[data-grantee]').forEach(b=>b.onchange=()=>grant(id,b.dataset.grantee,b.checked));}renderRoster();}async function open(id){if(contextLocked){context.notify('Room access is locked. Reload before opening more editors.');return;}if(panes.has(id)||opening.has(id))return;if(panes.size+opening.size>=6){context.notify('Up to six editors can be open at once. Close one to open another.');return;}const person=people().find(p=>p.id===id);if(!person)return;const generation=epoch,requestId=++requestSerial;opening.set(id,requestId);try{const value=await call(id);if(generation!==epoch||opening.get(id)!==requestId||!root())return;panes.set(id,{...value,text:value.code,dirty:false,locked:false});renderPanes();}catch(e){if(generation!==epoch)return;if(id===myId()){panes.set(id,{learner:person,text:'',revision:0,canEdit:false,shared:false,error:e.message,locked:true});renderPanes();}else context.notify(person.handle+': '+e.message);}finally{if(opening.get(id)===requestId)opening.delete(id);}}function close(id){const p=panes.get(id);if(!p||id===myId())return;if(p.dirty&&!confirm('Close this editor and discard unsaved changes? Copy or save first to keep them.'))return;panes.delete(id);renderPanes();}async function copy(id){try{await navigator.clipboard.writeText(field(id).value);setStatus(id,'Copied. Review peer code as untrusted before running it.');}catch{field(id)?.focus();field(id)?.select();setStatus(id,'Code selected. Use your keyboard or device menu to copy.');}}async function save(id){const p=panes.get(id);if(!p||p.locked||!p.canEdit)return;const generation=epoch,sent=field(id).value,rev=p.revision;const b=node(id).querySelector('[data-command="save"]');b.disabled=true;setStatus(id,'Saving…');try{const r=await call(id,{action:'save',revision:rev,code:sent});if(generation!==epoch||panes.get(id)!==p)return;p.revision=r.revision;p.code=sent;p.text=field(id).value;p.dirty=p.text!==sent;p.conflict=false;p.status=p.dirty?'Previous edits saved; newer edits need saving.':'Saved version '+r.revision;setStatus(id,p.status);node(id).querySelector('.pane-change').hidden=true;}catch(e){if(generation!==epoch||panes.get(id)!==p||!node(id))return;setStatus(id,e.message);if(e.status===403||e.status===401)locked(id,e.message);if(e.status===409){p.conflict=true;node(id).querySelector('.pane-change').hidden=false;}}finally{if(generation===epoch&&panes.get(id)===p&&node(id))node(id).querySelector('[data-command="save"]').disabled=!p.canEdit||p.locked;}}
async function reload(id){const p=panes.get(id);if(!p)return;if(p.dirty&&!confirm('Replace unsaved text with the latest saved code? Copy your edits first if needed.'))return;const initial=p.text,generation=epoch,lockVersion=p.lockVersion||0;try{const r=await call(id);if(generation!==epoch||panes.get(id)!==p)return;if((p.lockVersion||0)!==lockVersion)return;if(field(id).value!==initial){setStatus(id,'You typed while loading. Your newer edits were kept; choose Load latest again if needed.');return;}panes.set(id,{...r,text:r.code,dirty:false,locked:false});renderPanes();}catch(e){if(generation===epoch&&panes.get(id)===p)locked(id,e.message);}}
async function permissionChange(id,body,message){const p=panes.get(id);if(!p||p.permissionsBusy||p.permissionsUnknown)return;const generation=epoch;p.permissionsBusy=true;renderPanes();try{await call(id,body);const authoritative=await call(id);if(generation!==epoch||panes.get(id)!==p)return;p.shared=authoritative.shared;p.editors=authoritative.editors||[];p.permissionsUnknown=false;p.status=message;}catch(e){if(generation!==epoch||panes.get(id)!==p)return;p.permissionsUnknown=true;p.status='Permission update could not be confirmed: '+e.message+' Choose Load latest to check the current setting.';}finally{if(generation===epoch&&panes.get(id)===p){p.permissionsBusy=false;renderPanes();}}}
async function share(id,shared){const p=panes.get(id);if(!p||p.permissionsBusy||p.permissionsUnknown)return;if(shared&&!confirm('Share your saved code with all invited members of this room? Unsaved text stays local until you save.')){renderPanes();return;}await permissionChange(id,{action:'share',shared},shared?'Your saved editor is visible to invited room members.':'Your editor is private. Previous editing grants were removed.');}
async function grant(id,target,allow){const p=panes.get(id);if(!p||p.permissionsBusy||p.permissionsUnknown)return;if(allow&&!confirm('Allow this learner to edit your shared code in this room?')){renderPanes();return;}await permissionChange(id,{action:'grant',granteeId:target,allow},'Editing permissions updated.');}
async function poll(){if(inflight||document.hidden||contextLocked||!context||!root())return;inflight=true;const generation=epoch;try{await Promise.all([...panes.keys()].map(async id=>{const p=panes.get(id),lockVersion=p.lockVersion||0;try{const r=await call(id);if(generation!==epoch||panes.get(id)!==p||(p.lockVersion||0)!==lockVersion)return;const ed=field(id);if(!ed)return;p.canEdit=r.canEdit;p.shared=r.shared;p.locked=false;ed.readOnly=!r.canEdit;node(id).querySelector('[data-command="save"]').disabled=!r.canEdit;node(id).querySelector('.pane-access').textContent=(r.canEdit?'EDIT ACCESS':'VIEW ONLY')+' · '+(r.shared?'SHARED':'PRIVATE');if(r.revision>p.revision){if(p.dirty){p.conflict=true;node(id).querySelector('.pane-change').hidden=false;}else{p.revision=r.revision;p.code=r.code;p.text=r.code;ed.value=r.code;node(id).querySelector('.line-gutter').textContent=Array.from({length:Math.max(18,r.code.split('\n').length)},(_,i)=>i+1).join('\n');setStatus(id,'Updated to saved version '+r.revision);}}}catch(e){if(generation===epoch&&panes.get(id)===p)locked(id,e.message);}}));}finally{inflight=false;}}
window.CodeTrailSplit={mount(c){const same=context?.roomId===c.roomId&&context?.state.me.id===c.state.me.id;context=c;contextLocked=!!c.state.room.closed;epoch++;if(!same)panes=new Map();opening=new Map();shell();if(panes.size)renderPanes();else open(myId());clearInterval(timer);timer=setInterval(poll,4000);},update(c){context={...context,state:c};contextLocked=!!c.room?.closed;renderRoster();if(c.room?.closed)this.lock('This room is closed.');},lock(message){contextLocked=true;opening.clear();for(const id of panes.keys())locked(id,message);},replaceOwnCode(code,language){const p=panes.get(myId()),editor=field(myId());if(!p||!editor)return{ok:false,message:'Your own editor is still loading. Try again in a moment.'};if(contextLocked||p.locked||!p.canEdit)return{ok:false,message:'Your editor is read-only right now. Check room access.'};if(language!==context.state.room.language)return{ok:false,message:'This room uses '+context.state.room.language+'. Open a '+language+' room or use the full lesson workspace for this example.'};if(typeof code!=='string'||code.length>16000)return{ok:false,message:'This example is too long for the shared editor.'};if(editor.value.trim()&&editor.value!==code&&!confirm('Replace the code in your own editor? Copy or save your existing work first if you want to keep it. Other learners’ editors will not change.'))return{ok:false,message:'Your code was left unchanged.'};p.text=code;p.dirty=true;p.status='Learning code loaded locally. Review it, then choose Save when ready.';editor.value=code;renderPanes();return{ok:true,message:'Loaded into your own editor only. Nothing was run or saved automatically.'};},hasUnsaved(){return[...panes.values()].some(p=>p.dirty);},debugState(){return [...panes].map(([id,p])=>({id,dirty:p.dirty,revision:p.revision}));}};addEventListener('beforeunload',e=>{if(window.CodeTrailSplit.hasUnsaved()){e.preventDefault();e.returnValue='';}});
})();
